import time
import logging
import traceback
from taf.internal.managedobject import ManagedObject
from taf.internal.managed.ssh.managed_ssh_connection import ManagedSshConnection
from taf.internal.ue.pioneer.api.facade import Pioneer
from taf.ue.pioneer.client.ue import UE, UEInfo
from taf.ue.pioneer.client.decorate import decorate_command_with_response_state_check
from taf.ue.pioneer.client.exception import (NoUEConnectedError, NoUEWithIMSIORIMEI, InvalidParameterValue)
from taf.ue.pioneer.client.env import RemoteWindowsEnvironment
from taf.ue.pioneer.client.adb import ADB


class PioneerService(ManagedObject):
    def __init__(self, host, port=None, ssh_port=None, ssh_username=None, ssh_password=None, timeout=None):
        super(PioneerService, self).__init__()
        self._timeout = timeout or 60

        self._pioneer = Pioneer(host, port, timeout=self._timeout)
        self._decorate_command_execute(self._pioneer.commands)

        self._ues_info = []
        self._ssh_port = ssh_port or 22
        self._ssh_username = ssh_username
        self._ssh_password = ssh_password
        self.add_prerequisite(self._pioneer)
        self._ssh_executor = self._create_ssh_connection()
        self._service_adb = ADB(self._ssh_executor)

    @property
    def adb(self):
        return self._service_adb

    def _create_ssh_connection(self):
        return ManagedSshConnection(
            host=self._pioneer.host,
            user=self._ssh_username,
            password=self._ssh_password,
            port=self._ssh_port).ssh_connection

    def get_pid_for_listening_port(self):
        cnn = self._create_ssh_connection()
        cnn.connect()
        env = RemoteWindowsEnvironment(cnn)
        pid = env.get_pid_for_listening_port(self._pioneer.port)
        cnn.disconnect()
        return pid

    def is_pioneer_pid(self, pid):
        cnn = self._create_ssh_connection()
        cnn.connect()
        env = RemoteWindowsEnvironment(cnn)
        result = env.is_app_pid(pid, "RemoteService.exe")
        cnn.disconnect()
        return result

    def _decorate_command_execute(self, commands):
        for command in commands:
            decorated = decorate_command_with_response_state_check(command.execute)
            setattr(command, "execute", decorated)

    def _setup(self):
        try:
            self._ssh_executor.connect()
        except Exception as e:
            logging.warning("default ssh connection failed for exception {}, {}. \r\n "
                            "will impact the ssh relevant keywords".format(e, traceback.format_exc()))

    def _teardown(self):
        self._disconnect_ues(timeout=self._timeout)
        self._ssh_executor.disconnect()

    def _get_ue_count(self, timeout=None):
        return self._pioneer.AutoCheck(until_timeout=timeout).bean.Param.Count

    def _connect_ues(self, timeout=None):
        self._pioneer.ConnectEQ(until_timeout=timeout)
        logging.debug("WA, wait 20s for pioneer stable after connecteq")
        time.sleep(20)  # WA for unstable connecteq, if the escape is no enough, the next next command maybe abnormal

    def _disconnect_ues(self, timeout=None):
        self._pioneer.DisConnectEQ(until_timeout=timeout)

    def prepare_ues(self):
        ue_count = self._get_ue_count()
        if not ue_count:
            raise NoUEConnectedError()
        self._connect_ues(timeout=self._timeout)
        return self._retrive_ues_info(ue_count, timeout=self._timeout)

    def release_ues(self):
        self._disconnect_ues(timeout=self._timeout)
        self._ues_info = []

    def refresh_ues_info(self, timeout):
        ue_count = self._get_ue_count()
        if not ue_count:
            raise NoUEConnectedError()
        return self._retrive_ues_info(ue_count, timeout)

    def _retrive_ues_info(self, ue_count, timeout):
        self._ues_info = []
        for eqindex in range(1, ue_count + 1):
            ue_info = self._retrive_ue_info(eqindex, timeout)
            self._ues_info.append(ue_info)
        return self._ues_info

    def _get_imei(self, eqindex, timeout=None):
        back = self._pioneer.SendAT(eqindex, 'AT+CGSN', 5000, until_timeout=timeout).bean.Param.Back
        if back:
            return back.split(',')[0]
        return ''

    def _retrive_ue_info(self, eqindex, timeout=None):
        imsi = self._pioneer.GetParamIMSI(eqindex, until_timeout=timeout).bean.Param.IMSI
        if not imsi:
            # for ue without SIM card
            logging.warning("no imsi was got from eqindex {} device".format(eqindex))

        imei = self._get_imei(eqindex, timeout)
        if not imei:
            logging.warning("no imei was got from eqindex {} device".format(eqindex))
        return UEInfo(eqindex=eqindex, imsi=imsi, imei=imei)

    @property
    def ues_info(self):
        return self._ues_info

    def require_ue_from_eqindex(self, eqindex=1, serial_number=None):
        ue_info = self._find_ue_info_from_eqindex(eqindex)
        if not ue_info:
            ue_info = self._retrive_ue_info(eqindex)
        self._ues_info.append(ue_info)
        adb = ADB(self._ssh_executor, serial_number)
        return UE(self._pioneer, adb, self._ues_info[0], self)

    def _find_ue_info_from_eqindex(self, eqindex):
        if eqindex < 1:
            raise AttributeError("eqindex must start from 1")

        for ue_info in self._ues_info:
            if ue_info.eqindex == eqindex:
                return ue_info
        return None

    def require_ue(self, serial_number=None, imsi=None, imei=None): # noqa C901
        if not imsi and not imei:
            return self.require_ue_from_eqindex(eqindex=1)

        matched_ue_info = None
        for ue_info in self._ues_info:
            if imsi and imei:
                if ue_info.imsi == imsi and ue_info.imei == imei:
                    matched_ue_info = ue_info
                    break
            elif imei:
                if ue_info.imei == imei:
                    matched_ue_info = ue_info
                    break
            elif imsi:
                if ue_info.imsi == imsi:
                    matched_ue_info = ue_info
                    break
        else:
            raise NoUEWithIMSIORIMEI("imsi or imei {} is absent".format(imsi))

        adb = ADB(self._ssh_executor, serial_number)
        return UE(self._pioneer, adb, matched_ue_info, self)

    def release_ue(self, ue):
        self._ues_info.remove(self._find_ue_info_from_eqindex(ue.eqindex))

    def start_log(self, logpath, logname, timeout=None):
        return self._pioneer.StartLog(logpath, logname, until_timeout=timeout)

    def stop_log(self, timeout=None):
        return self._pioneer.StopLog(until_timeout=timeout)

    def export_log_file(self, templatename, exportfilename, logfile, timeout=None):
        return self._pioneer.ExportLogFile(templatename,
                                           exportfilename,
                                           logfile,
                                           until_timeout=timeout)

    def export_message_detail(self, exportfilename, logfile, timeout=None):
        return self._pioneer.ExportMessageDetail(exportfilename, logfile, until_timeout=timeout)

    def export_layer1_msg(self, exportfilename, logfile, timeout=None):
        return self._pioneer.ExportLayer1Msg(exportfilename, logfile, until_timeout=timeout)

    def start_statistics(self, ues, until_timeout=None):
        return self._pioneer.StartStatistics([ue.eqindex for ue in ues], until_timeout=until_timeout)

    def stop_statistics(self, ues, until_timeout=None):
        return self._pioneer.StopStatistics([ue.eqindex for ue in ues], until_timeout=until_timeout)

    @staticmethod
    def _download_file(remote_path, connection, local_path):
        fp = connection.files
        log_msg = "Downloading file to {}:\n"
        log_msg += "Remote path: {}"
        log_msg = log_msg.format(connection, remote_path)
        logging.info(log_msg)

        logging.info("Downloading file: {}".format(local_path))
        fp.get(remote_path, local_path)

    def download_file(self, remote_src_file, local_dest_file):
        self._download_file(remote_src_file, self._ssh_executor, local_dest_file)

    def remove_remote_files(self, folder_path):
        return self._ssh_executor.execute("rm -f {}/*".format(folder_path))

    def attach(self, ues, uemode, until_timeout=None):
        return self._pioneer.Attach(eqindex=[ue.eqindex for ue in ues], uemode=uemode, until_timeout=until_timeout)

    def detach(self, ues, withpdu, until_timeout=None):
        return self._pioneer.Detach(eqindex=[ue.eqindex for ue in ues], withpdu=withpdu, until_timeout=until_timeout)

    def poweron(self, ues, until_timeout=None):
        return self._pioneer.PowerOn(eqindex=[ue.eqindex for ue in ues], until_timeout=until_timeout)

    def poweroff(self, ues, until_timeout=None):
        return self._pioneer.PowerOff(eqindex=[ue.eqindex for ue in ues], until_timeout=until_timeout)

    def starttraffic(self, ues, until_timeout=None, **kwargs): # noqa C901
        direction = int(kwargs["direction"])
        """
        start both uplink and downlink directions traffic if direction is 2.
        """
        if direction == 2:
            if len(ues) != 1:
                raise InvalidParameterValue("multi ues {} not supported in both directions traffic".format(ues))

            eqindex = ues[0].eqindex

            param_names = ["Protocol",
                           "Address",
                           "Port",
                           "TestTime",
                           "Bandwidth",
                           "BufferSize",
                           "PacketSize",
                           "IperfType",
                           "Direction",
                           "ThreadCount"]

            uplink_test_params = {}
            for name in param_names:
                lowername = name.lower()
                ul_name = 'ul_' + lowername
                if ul_name in kwargs:
                    uplink_test_params[name] = kwargs[ul_name]
                else:
                    uplink_test_params[name] = kwargs[lowername]
            uplink_test_params["Direction"] = 0

            downlink_test_params = {}
            for name in param_names:
                lowername = name.lower()
                dl_name = 'dl_' + lowername
                if dl_name in kwargs:
                    downlink_test_params[name] = kwargs[dl_name]
                else:
                    downlink_test_params[name] = kwargs[lowername]
            downlink_test_params["Direction"] = 1

            iperftests = [{"TestKind": "Iperf", "TestParam": uplink_test_params},
                          {"TestKind": "Iperf", "TestParam": downlink_test_params}]
            return self._pioneer.StartCompositeTestPlan(eqindex, iperftests, until_timeout=until_timeout)
        else:
            return self._pioneer.StartTraffic(eqindex=[ue.eqindex for ue in ues],
                                              protocol=kwargs["protocol"],
                                              address=kwargs["address"],
                                              port=kwargs["port"],
                                              testtime=kwargs["testtime"],
                                              bandwidth=kwargs["bandwidth"],
                                              buffersize=kwargs["buffersize"],
                                              packetsize=kwargs["packetsize"],
                                              iperftype=kwargs["iperftype"],
                                              direction=kwargs["direction"],
                                              threadcount=kwargs["threadcount"],
                                              until_timeout=until_timeout)

    def stoptest(self, eqindex, until_timeout=None):
        return self._pioneer.StopTest(eqindex=eqindex, until_timeout=until_timeout)

    def startup(self, until_timeout=None):
        return self._pioneer.Startup(until_timeout=until_timeout)

    def shutdown(self, until_timeout=None):
        return self._pioneer.Shutdown(until_timeout=until_timeout)
